module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  localparam PTR_W  = $clog2(DEPTH) + 1;
  localparam ADDR_W = ($clog2(DEPTH) > 0) ? $clog2(DEPTH) : 1;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [PTR_W-1:0] wr_ptr, rd_ptr;

  // Pointers are PTR_W bits wide (one extra MSB). Equal pointers mean empty;
  // pointers equal except for the MSB mean full.
  assign empty = (wr_ptr == rd_ptr);
  assign full  = (wr_ptr == (rd_ptr ^ {1'b1, {(PTR_W-1){1'b0}}}));

  assign waddr = wr_ptr[ADDR_W-1:0];
  assign raddr = rd_ptr[ADDR_W-1:0];

  wire do_write = wr_en & ~full;
  wire do_read  = rd_en & ~empty;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr <= {PTR_W{1'b0}};
      rd_ptr <= {PTR_W{1'b0}};
      dout   <= {WIDTH{1'b0}};
    end else begin
      if (do_write) begin
        mem[waddr] <= din;
        wr_ptr <= wr_ptr + 1'b1;
      end
      if (do_read) begin
        dout   <= mem[raddr];
        rd_ptr <= rd_ptr + 1'b1;
      end
    end
  end

endmodule
